-- DevBase end-user directory schema. Identifiers are UUID v7 values generated by the server.

CREATE TABLE projects (
    id          uuid PRIMARY KEY,
    tenant_id   uuid NOT NULL,
    name        text NOT NULL CHECK (name <> '' AND octet_length(name) <= 256),
    -- user_count is the atomic quota counter; it never changes version.
    user_count  bigint NOT NULL DEFAULT 0 CHECK (user_count >= 0),
    version     bigint NOT NULL DEFAULT 1,
    created_at  timestamptz NOT NULL,
    updated_at  timestamptz NOT NULL
);
-- Project names are unique ignoring case. lower() follows the database locale, which differs
-- between deployments (Turkish and others map case differently), so name the comparison
-- explicitly: the ICU root locale at strength level 2 ignores case, keeps accents and does not
-- depend on the database locale. A nondeterministic collation is valid in a unique index, and
-- this migration therefore requires PostgreSQL built with ICU.
CREATE COLLATION project_name_ci (provider = icu, locale = 'und-u-ks-level2', deterministic = false);
CREATE UNIQUE INDEX projects_tenant_name ON projects (tenant_id, (name COLLATE project_name_ci));
CREATE INDEX projects_tenant_order ON projects (tenant_id, created_at, id);

CREATE TABLE api_keys (
    id          uuid PRIMARY KEY,
    project_id  uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    permission  smallint NOT NULL CHECK (permission IN (1, 2)),
    -- secret_hash is the SHA-256 digest of the key secret. The raw key is never stored.
    secret_hash bytea NOT NULL,
    created_at  timestamptz NOT NULL,
    expires_at  timestamptz,
    revoked_at  timestamptz
);
CREATE INDEX api_keys_project_order ON api_keys (project_id, created_at, id);

CREATE TABLE end_users (
    id          uuid PRIMARY KEY,
    project_id  uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    external_id text NOT NULL CHECK (external_id <> '' AND octet_length(external_id) <= 256),
    name        text CHECK (octet_length(name) <= 256),
    email       text CHECK (octet_length(email) <= 254),
    metadata    jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(metadata) = 'object'),
    version     bigint NOT NULL DEFAULT 1,
    created_at  timestamptz NOT NULL,
    updated_at  timestamptz NOT NULL,
    UNIQUE (project_id, external_id)
);
CREATE INDEX end_users_order ON end_users (project_id, created_at, id);

-- replays holds 24-hour idempotency records. A scrubbed record has no response or
-- fingerprint so deleted personal data cannot be replayed or resurrected.
CREATE TABLE replays (
    principal       text NOT NULL,
    idempotency_key text NOT NULL,
    operation       text NOT NULL,
    tenant_id       uuid NOT NULL,
    project_id      uuid,
    target_user_id  uuid,
    fingerprint     bytea NOT NULL,
    response        bytea,
    scrubbed        boolean NOT NULL DEFAULT false,
    created_at      timestamptz NOT NULL,
    expires_at      timestamptz NOT NULL,
    PRIMARY KEY (principal, idempotency_key)
);
CREATE INDEX replays_expiry ON replays (expires_at);
CREATE INDEX replays_project ON replays (project_id) WHERE project_id IS NOT NULL;
CREATE INDEX replays_user ON replays (target_user_id) WHERE target_user_id IS NOT NULL;

-- audit_events excludes names, email addresses, metadata, raw keys and external user IDs.
CREATE TABLE audit_events (
    id          uuid PRIMARY KEY,
    occurred_at timestamptz NOT NULL,
    action      text NOT NULL,
    actor       text NOT NULL,
    target_id   uuid NOT NULL,
    trace_id    text NOT NULL
);
CREATE INDEX audit_events_time ON audit_events (occurred_at);
CREATE INDEX audit_events_target ON audit_events (target_id);
